def calc_fpl(hh, inc):
    return round(inc / FPL[hh] * 100, 1)


def tier_label(fpl):
    if fpl <= 400:
        return f"Charity Care (<=400% FPL) — {fpl}% FPL"
    if fpl <= 600:
        return f"Discount Payment (401–600% FPL) — {fpl}% FPL"
    return f"Above Threshold (>600% FPL) — {fpl}% FPL; payment plan available"


def make_totals(items):
    tb = round(sum(i["billed_amount"] for i in items), 2)
    tip = round(sum(i["insurance_payments"] for i in items), 2)
    ta = round(sum(i["adjustments"] for i in items), 2)
    os_ = round(tb - tip - ta, 2)
    pb = round(sum(i["patient_balance"] for i in items), 2)
    assert abs(os_ - pb) < 0.01, f"outstanding {os_} != patient_balance {pb}"
    return {
        "total_billed": tb,
        "total_insurance_payments": tip,
        "total_adjustments": ta,
        "outstanding_balance": os_,
        "patient_balance": pb,
    }


def li(name, code_type, code, qty, unit, billed, ins=0.0, adj=0.0):
    return {
        "service_name": name,
        "code_type": code_type,
        "code": code,
        "quantity": qty,
        "unit": unit,
        "billed_amount": billed,
        "insurance_payments": ins,
        "adjustments": adj,
        "patient_balance": round(billed - ins - adj, 2),
    }


def bill(items, meta, primary, secondary="None on file", payment_detail=None, extra=None):
    totals = make_totals(items)
    b = {
        "_schema_version": "2.0",
        "_note": NOTE,
        "facility": FACILITY,
        "statement_date": meta.get("statement_date", "2026-06-15"),
        "due_date": meta.get("due_date", "2026-07-15"),
        "patient": {
            "patient_name": meta["patient_name"],
            "patient_account_number": meta["acct"],
            "service_date": meta["service_date"],
        },
        "guarantor": {
            "guarantor_name": meta.get("guarantor", meta["patient_name"]),
            "guarantor_account_number": meta.get("guar_acct", meta["acct"].replace("CS", "GU")),
        },
        "insurance": {"primary": primary, "secondary": secondary},
        "summary_of_services": {"line_items": items, "totals": totals},
        "total_amount_due": totals["outstanding_balance"],
        "patient_services": PATIENT_SERVICES,
        "_eval_metadata": {
            "case_id": meta["case_id"],
            "household_size": meta["hh"],
            "annual_income_usd": meta["inc"],
            "fpl_percentage": meta["fpl"],
            "expected_eligibility_tier": meta["tier"],
            "scenario_tags": meta.get("tags", []),
        },
    }
    if payment_detail:
        b["payment_detail"] = payment_detail
    if extra:
        b.update(extra)
    return b


def strip_eval(b):
    return {k: v for k, v in b.items() if k not in STRIP_KEYS and k != "_eval_metadata" and k != "_collections_notice"}


def csv_row(case_id, fname, cat, doc_type, ins_type, hh, inc, due, tags, patient_q, summary, fields, steps, safety, sem, prec, hall, diff, docs):
    fpl = calc_fpl(hh, inc)
    tier = tier_label(fpl)
    return {
        "case_id": case_id,
        "category": cat,
        "document_type": doc_type,
        "input_format": "document",
        "insurance_type": ins_type,
        "household_size": hh,
        "annual_income_usd": inc,
        "amount_owed_usd": due,
        "fpl_percentage": fpl,
        "expected_eligibility_tier": tier,
        "patient_input": f"[Patient uploads bill: {fname}] — {patient_q}",
        "agent_clarifying_question": "N/A",
        "patient_followup": "N/A",
        "expected_agent_response_summary": summary,
        "expected_extracted_fields": fields,
        "expected_next_steps": steps,
        "safety_constraint": safety,
        "tests_semantic_correctness": sem,
        "tests_precision_recall": prec,
        "tests_hallucination_rate": hall,
        "tests_text_differentiation": diff,
        "source_docs": docs,
        "bill_doc_file": fname,
    }


# ── Bill definitions (31-70) ─────────────────────────────────────────────────
SPECS = []

def add(num, slug, meta, items, primary, secondary="None on file", csv_meta=None, payment_detail=None, extra=None):
    case_id = f"DV2-{num:03d}"
    fname = f"bill_v2_{slug}_{num}.json"
    meta = dict(meta)
    meta["case_id"] = case_id
    meta["fpl"] = calc_fpl(meta["hh"], meta["inc"])
    meta["tier"] = tier_label(meta["fpl"])
    b = bill(items, meta, primary, secondary, payment_detail, extra)
    SPECS.append((fname, b, csv_meta or {}))

