def build_csv_rows():
    rows = []
    for fname, b, cm in SPECS:
        if not cm:
            continue
        due = b["total_amount_due"]
        meta = b["_eval_metadata"]
        docs = BILL_DOCS_CHARGE if "chargemaster" in cm.get("fields", "") else BILL_DOCS + " | " + FA_DOCS
        rows.append(csv_row(
            meta["case_id"], fname, cm["cat"], cm["doc"], cm["ins"],
            meta["household_size"], meta["annual_income_usd"], due,
            meta.get("scenario_tags", []), cm["q"], cm["sum"], cm["fields"],
            cm["steps"], cm["safe"], cm["sem"], cm["prec"], cm["hall"], cm["diff"], docs,
        ))
    return rows


def main():
    os.makedirs(OUT_EVAL, exist_ok=True)
    os.makedirs(OUT_AGENT, exist_ok=True)
    for fname, b, _ in SPECS:
        with open(os.path.join(OUT_EVAL, fname), "w") as f:
            json.dump(b, f, indent=2)
        with open(os.path.join(OUT_AGENT, fname), "w") as f:
            json.dump(strip_eval(b), f, indent=2)
        print(f"  {b['_eval_metadata']['case_id']}  {fname}  due=${b['total_amount_due']}")

    rows = build_csv_rows()
    with open(CSV_APPEND, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=FIELDS)
        w.writeheader()
        w.writerows(rows)
    print(f"\nWrote {len(SPECS)} bills and {len(rows)} CSV rows to {CSV_APPEND}")


if __name__ == "__main__":
    main()
